@push('scripts')<script>const scope=document.getElementById('recipient-scope'),users=document.getElementById('users'),wrap=document.getElementById('user-wrap'),count=document.getElementById('recipient-count');function recipients(){wrap.classList.toggle('hidden',scope.value==='all');users.multiple=scope.value!=='single';if(scope.value==='single'&&users.selectedOptions.length>1)[...users.options].forEach((o,i)=>{if(i>0)o.selected=false});count.textContent=scope.value==='all'?{{ $users->count() }}:users.selectedOptions.length;}scope?.addEventListener('change',recipients);users?.addEventListener('change',recipients);recipients();</script>@endpush
